
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_b3lyp_mcm2_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_b3lyp_mcm2", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.540299403525433e+00, -3.473905058185763e+00, -3.380920936513324e+00, -3.252219082555593e+00, -3.077061120194212e+00, -2.844375583385682e+00, -2.545745379750668e+00, -2.180672671279710e+00, -1.763154777022788e+00, -1.323137581041270e+00, -8.914178742985365e-01, -6.021209162810570e-01, -5.191216848870412e-01, -4.321705396167733e-01, -3.139101866868934e-01, -1.966825204550613e-01, -1.146642548323127e-01, -7.316315189047951e-02, -4.514324939293651e-02, -3.049276016354347e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


